from __future__ import annotations

import json
from typing import Any


def def_encode_dashboard_payload(payload: dict[str, Any]) -> str:
    """Encode payload safely for an inline, dependency-free script block."""
    encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
    return encoded.replace("</", "<\\/").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")


def def_build_dashboard_html(payload: dict[str, Any]) -> str:
    """Build the integrated classification and group-flow single-file U/I."""
    encoded = def_encode_dashboard_payload(payload)
